using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.SetIsOriginAllowed(origin=>Uri.TryCreate(origin,UriKind.Absolute,out var uri)&&(uri.Host=="localhost"||uri.Host=="127.0.0.1")&&(uri.Port==5173||uri.Port==5174)).AllowAnyHeader().AllowAnyMethod()));builder.Services.AddDbContext<CatalogDb>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("Saloon")??throw new InvalidOperationException("Set ConnectionStrings__Saloon.")));var app=builder.Build();app.UseCors();app.MapGet("/health",()=>Results.Ok(new{service="catalog",status="healthy"}));
app.MapGet("/api/services",async(CatalogDb db)=>Results.Ok(await db.Services.Where(s=>s.IsActive).OrderBy(s=>s.Name).ToListAsync()));
app.MapPost("/api/services",async(SaveService r,CatalogDb db)=>{if(string.IsNullOrWhiteSpace(r.Name)||r.Price<0||r.DurationMinutes<5)return Results.BadRequest("Name, non-negative price, and duration of at least 5 minutes are required.");var s=new Service{Name=r.Name.Trim(),Category=r.Category,DurationMinutes=r.DurationMinutes,Price=r.Price,IsActive=true};db.Services.Add(s);await db.SaveChangesAsync();return Results.Created($"/api/services/{s.Id}",s);});
app.MapPut("/api/services/{id:int}",async(int id,SaveService r,CatalogDb db)=>{var s=await db.Services.FindAsync(id);if(s is null)return Results.NotFound();if(string.IsNullOrWhiteSpace(r.Name)||r.Price<0||r.DurationMinutes<5)return Results.BadRequest();s.Name=r.Name.Trim();s.Category=r.Category;s.DurationMinutes=r.DurationMinutes;s.Price=r.Price;await db.SaveChangesAsync();return Results.Ok(s);});
app.MapDelete("/api/services/{id:int}",async(int id,CatalogDb db)=>{var s=await db.Services.FindAsync(id);if(s is null)return Results.NotFound();s.IsActive=false;await db.SaveChangesAsync();return Results.NoContent();});app.Run();
record SaveService(string Name,string Category,int DurationMinutes,decimal Price);
class CatalogDb(DbContextOptions<CatalogDb> o):DbContext(o){public DbSet<Service> Services=>Set<Service>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Service>().Property(s=>s.Price).HasColumnType("decimal(10,2)");b.Entity<Service>().HasData(new Service{Id=1,Name="Haircut & blow dry",Category="Hair",DurationMinutes=60,Price=500},new Service{Id=2,Name="Head massage",Category="Wellness",DurationMinutes=45,Price=600},new Service{Id=3,Name="Hair coloring",Category="Hair",DurationMinutes=120,Price=7500},new Service{Id=4,Name="Manicure",Category="Nails",DurationMinutes=60,Price=2200},new Service{Id=5,Name="Beard trim",Category="Grooming",DurationMinutes=30,Price=1200});}}
class Service{public int Id{get;set;}public string Name{get;set;}="";public string Category{get;set;}="";public int DurationMinutes{get;set;}public decimal Price{get;set;}public bool IsActive{get;set;}=true;}
